#!/usr/bin/env python3
import argparse,re,tempfile
from pathlib import Path
MAP={"( ͡° ͜ʖ ͡°)":"+","(♥ ͜ʖ♥)":"-","ᕦ( ͡°ヮ ͡°)ᕥ":">","(∩ ͡° ͜ʖ ͡°)⊃━☆ﾟ.*":"<","(> ͜ʖ(∩ ͡° ͜ʖ ͡°)⊃━☆ﾟ.*)":".","( ͡°(":"[",") ͡°)":"]"}
FLAG_RE=re.compile(r"[A-Za-z0-9_]*ctf\{[^}\n\r]+\}|[A-Za-z0-9_]+\{[^}\n\r]+\}",re.I)
def to_bf(s):
    toks=sorted(MAP.items(),key=lambda x:len(x[0]),reverse=True);i=0;o=[]
    while i<len(s):
        for t,c in toks:
            if s.startswith(t,i): o.append(c); i+=len(t); break
        else:
            if s[i] in "><+-.,[]": o.append(s[i])
            i+=1
    return "".join(o)
def run(code):
    j={};st=[]
    for i,c in enumerate(code):
        if c=="[": st.append(i)
        elif c=="]": a=st.pop();j[a]=i;j[i]=a
    t=[0]*30000;p=ip=0;out=[]
    while ip<len(code):
        c=code[ip]
        if c==">": p+=1
        elif c=="<": p-=1
        elif c=="+": t[p]=(t[p]+1)&255
        elif c=="-": t[p]=(t[p]-1)&255
        elif c==".": out.append(chr(t[p]))
        elif c=="[" and t[p]==0: ip=j[ip]
        elif c=="]" and t[p]!=0: ip=j[ip]
        ip+=1
    return "".join(out)
def solve(attachment_path,**kwargs):
    text=Path(attachment_path).read_text(encoding=kwargs.get("encoding","utf-8"),errors="ignore")
    bf=to_bf(text);out=run(bf);m=FLAG_RE.search(out)
    return {"flag":m.group(0) if m else None,"artifacts":[],"evidence":f"translated_len={len(bf)} output={out!r}"}
def self_test():
    R={v:k for k,v in MAP.items()}
    em=R["+"]*8+R["["]+R[">"]+R["+"]*8+R["<"]+R["-"]+R["]"]+R[">"]+R["+"]+R["."]
    with tempfile.TemporaryDirectory() as d:
        a=Path(d)/"a.bf";b=Path(d)/"b.txt";a.write_text("++++++++[>++++++++<-]>+.",encoding="utf-8");b.write_text(em,encoding="utf-8")
        ea,eb=solve(str(a))["evidence"],solve(str(b))["evidence"]
        ok="output='A'" in ea and "output='A'" in eb
        print("SELF_TEST expected_output=A");print(ea);print(eb);print("SELF_TEST","PASS" if ok else "FAIL")
        return 0 if ok else 1
if __name__=="__main__":
    ap=argparse.ArgumentParser();ap.add_argument("attachment",nargs="?");ap.add_argument("--self-test",action="store_true");ns=ap.parse_args()
    raise SystemExit(self_test() if ns.self_test else (print(solve(ns.attachment)) or 0))
